insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-pe-128', 'chemistry-classification-of-elements-and-periodicity-in-properties', 'chemistry', 'Moseley found that the square root of the characteristic X-ray frequency varies linearly with atomic number as $\sqrt{\nu}=a(Z-b)$. This showed that', '["atomic mass is still the fundamental index","Z, not A, is the property that orders the elements","neutrons determine chemical behaviour","X-rays arise from valence-shell jumps only"]'::jsonb, 1, 'A plot of $\sqrt{\nu}$ against Z is a straight line; plots against atomic mass are irregular, so Z is the true periodic argument.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'hard', 'modern-law-table') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
